from decimal import Decimal

from ledger.chargebacks import chargeback
from ledger.entries import Journal
from ledger.payments import capture


class ChargebackTest(unittest.TestCase):
    def test_uses_the_captured_rate(self):
        j = Journal()
        p = capture(j, 'pay-1', 10000, 'EUR', 'USD', Decimal('1.0850'))
        e = chargeback(j, p, 10000, 'cb-1')
        self.assertEqual([l.amount_minor for l in e.lines if l.currency == 'USD'], [10850, -10850])
        self.assertEqual(e.reverses, 'pay-1')

